function run() {
	let output = "";

	let header = "{{itensMenuDinamico@header}}";
	let body = "{{itensMenuDinamico@body}}";
	let footer = "{{itensMenuDinamico@footer}}";


	if(header) output += `<b>${header}</b> \n \n`
	if(body) output += `${body} \n \n `
	if(footer) output += `<i>${footer}</i>`;

	return output;
}

function run(siteConsegnadoItemEscolhido) {
	let output = siteConsegnadoItemEscolhido.includes("value") ? JSON.parse(siteConsegnadoItemEscolhido) : {};

	if (!output.value) output = { value: siteConsegnadoItemEscolhido };

	return output;
}

function run(contadorPagina, itemEscolhido, itensFormatadoMenu) {
	try {
		itemEscolhido = JSON.parse(itemEscolhido);
		itensFormatadoMenu = JSON.parse(itensFormatadoMenu);
		contadorPagina = contadorPagina ? Number(contadorPagina) : 0;

		if (itemEscolhido.value.toLowerCase().includes("ver mais") || itensFormatadoMenu.some((opt) => opt.order === Number(itemEscolhido.value) && opt.text.toLowerCase().includes("ver mais"))) {
			contadorPagina += 1;
			return contadorPagina;
		}
		if (itemEscolhido.value.toLowerCase().includes("voltar") || itensFormatadoMenu.some((opt) => opt.order === Number(itemEscolhido.value) && opt.text.toLowerCase().includes("voltar"))) {
			contadorPagina -= 1;
			return contadorPagina;			
		}
		return	-1;
	} catch (e) {
		return 0;
	}
}

function run(itemEscolhido, itensFaqs, itensFormatadoMenu) {
	try {
		var ZWSP = "\u200B";
		var parse = function (v) { return typeof v === "string" ? JSON.parse(v) : v; };
		var norm = function (s) { return String(s == null ? "" : s).split(ZWSP).join("").trim().toUpperCase(); };

		// Todas as linhas originais do menu (com code, name etc.)
		var categorias = parse(itensFaqs);
		if (!Array.isArray(categorias)) categorias = [categorias];
		var itens = [];
		categorias.forEach(function (c) { itens = itens.concat((c && c.rows) || []); });

		var escolhido = parse(itemEscolhido) || {};

		// Opções exibidas na página atual (Blip Chat: {order,text,value} | WhatsApp: {title, rows:[{id,title}]})
		var opcoesMenu = [];
		try {
			(parse(itensFormatadoMenu) || []).forEach(function (m) {
				if (m && Array.isArray(m.rows)) {
					m.rows.forEach(function (r) { opcoesMenu.push({ chave: String(r.id), texto: r.title || "" }); });
				} else if (m) {
					opcoesMenu.push({ chave: String(m.order), texto: m.text || "", idx: m.value ? m.value.idx : undefined });
				}
			});
		} catch (e) { }

		var navegacao = function (txt) {
			txt = norm(txt);
			if (txt.indexOf("VER MAIS") >= 0) return { title: "Ver mais opções" };
			if (txt.indexOf("VOLTAR") >= 0) return { title: "Voltar" };
			return null;
		};
		var porMarcador = function (txt) {
			var qtd = String(txt || "").split(ZWSP).length - 1;
			return qtd > 0 && itens[qtd - 1] ? itens[qtd - 1] : null;
		};
		var temIdx = function (idx) { return idx !== undefined && idx !== null && idx !== "" && itens[Number(idx)]; };

		// 1) Blip Chat: o índice vem junto do valor clicado
		if (temIdx(escolhido.idx)) return itens[Number(escolhido.idx)];

		var valor = String(escolhido.value == null ? "" : escolhido.value);

		// 2) WhatsApp: título com marcador invisível identifica a linha
		var marcado = porMarcador(valor);
		if (marcado) return marcado;

		var limpo = valor.split(ZWSP).join("").trim();
		var nav = navegacao(limpo);
		if (nav) return nav;

		// 3) Número digitado/recebido (id da linha no WhatsApp ou ordem no Blip Chat)
		if (/^\d+$/.test(limpo)) {
			var op = opcoesMenu.filter(function (o) { return o.chave === limpo; })[0];
			if (op) {
				var navOp = navegacao(op.texto);
				if (navOp) return navOp;
				if (temIdx(op.idx)) return itens[Number(op.idx)];
				var marcadoOp = porMarcador(op.texto);
				if (marcadoOp) return marcadoOp;
			}
			if (itens[Number(limpo) - 1]) return itens[Number(limpo) - 1];
		}

		// 4) Texto: código, nome da condição ou título (somente se for único)
		var alvo = norm(limpo);
		var unico = function (lista) { return lista.length === 1 ? lista[0] : null; };
		var achado =
			unico(itens.filter(function (i) { return alvo && norm(i.code) === alvo; })) ||
			unico(itens.filter(function (i) { return alvo && norm(i.name || i.description) === alvo; })) ||
			unico(itens.filter(function (i) { return alvo && norm(i.title) === alvo; })) ||
			unico(itens.filter(function (i) { return alvo.length >= 3 && norm(i.name || i.description).indexOf(alvo) >= 0; }));

		return achado || false;
	} catch (e) {
		return false;
	}
}

function run(page, conveniosFormatados) {
	try {
		conveniosFormatados = JSON.parse(conveniosFormatados);
		page = Number(page);
		let counter = conveniosFormatados[page].length;

		// Índice global = quantidade de itens das páginas anteriores
		let offset = 0;
		for (let p = 0; p < page; p++) offset += conveniosFormatados[p].length;

		const opcoesFormatadas = conveniosFormatados[page].map((opcao, index) => ({
			order: index + 1,
			text:	opcao,
			type: "application/json",
			value: { value: opcao, idx: offset + index }
		}));

		if (conveniosFormatados[page + 1]) {
			opcoesFormatadas.push({
				order: counter + 1,
				text:	'Ver mais opções',
				type: "application/json",
		        value:{ value: "Ver mais opções" }
			})
			counter += 1;
		}

		if (page !== 0) opcoesFormatadas.push({
			order: counter + 1,
			text:	"Voltar",
			type: "application/json",
			value:{ value: "Voltar" },
		});

		return opcoesFormatadas;		
	} catch (err) {
		return 'Erro ao formatar menu de sites de consignacão';
	}
}

function formatterTitle(str) {
	let titleStyle = "{{itensMenuDinamico@titleStyle}}";

	if(!titleStyle) titleStyle = "none";
	titleStyle = titleStyle.toLowerCase();

	switch (titleStyle) {
		case "capitalize": {
			return str.split(" ").map((str2) => str2.charAt(0).toUpperCase() + str2.slice(1).toLowerCase()).join(" ");
		}
		case "lowercase": {
			return str.toLowerCase();
		}
		case "uppercase": {
			return str.toUpperCase();
		}
		case "normal": {
			return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
		}
		default: {
			return str;
		}
	}

}

function run(items) {
	try {
		items = JSON.parse(items);
		let itemsFiltered = [];

		Object.values(items).map((item) => { itemsFiltered = [].concat(itemsFiltered, item.rows) });

		if (itemsFiltered.length === 0) return false;

		const itemsMenu = [];
		let page = [];

		itemsFiltered.forEach((info, index, array) => {
			const item = formatterTitle(info.title.toString());
			page.push(item)
			if (((index + 1) % 8 === 0 && array.length > 10) || index === itemsFiltered.length - 1) {
				itemsMenu.push(page);
				page = [];
			}
		})

		return itemsMenu;
	} catch (e) {
		return false;
	}
}

