	}
}

function formatterTags(text) {
	const regexNegrito = /(<b>|<.b>)/g
	const regexItalico = /(<i>|<.i>)/g
	const regexTachado = /(<s>|<strike>|<.s>|<.strike>)/g
	const regexMonoespacado = /(<tt>|<.tt>)/g

	return text
		.replace(regexNegrito, "*")
		.replace(regexItalico, "_")
		.replace(regexTachado, "~")
		.replace(regexMonoespacado, "```")
}

