	const body = "{{itensMenuDinamico@body}}";
	const footer = "{{itensMenuDinamico@footer}}";
	let button = "{{itensMenuDinamico@button}}";

	const output = {
		"recipient_type": "individual",
		"type": "interactive",
		"interactive": {
			"type": "list",

		}
	}

	if (header) output.interactive.header = { type: "text", text: header };
	if (body) output.interactive.body = { text: formatterTags(body) };
	if (footer) output.interactive.footer = { text: footer };

	if(!button) button = "Menu"

	output.interactive.action = {
				"button": button,
				"sections": itensFormatadoMenu
			}

	return output;
}

