function run(page, itensFormatados) {
	try {
		itensFormatados = JSON.parse(itensFormatados);
		page = Number(page);
		const ZWSP = "\u200B";

		// Quantidade de linhas das páginas anteriores (ids e marcadores são globais)
		let seq = 0;
		for (let p = 0; p < page; p++) itensFormatados[p].forEach((sec) => { seq += sec.rows.length; });

		const opcoesFormatadas = itensFormatados[page].map((item) => ({
			...item,
			rows: item.rows.map((opcao) => {
				seq += 1;
				const output = { id: seq.toString() };
				if (opcao.title) output.title = opcao.title.slice(0, 24 - seq) + ZWSP.repeat(seq);
				if (opcao.description) output.description = opcao.description.slice(0, 72);
				return output;
			})
		}));

		let counter = seq;
		let navigation = "{{itensMenuDinamico@navigation}}";
		if(!navigation) navigation = "Navegação"

		const addNav = (titulo) => {
			counter += 1;
			const idx = opcoesFormatadas.findIndex((item) => item.title === navigation);
			const row = { id: counter.toString(), title: titulo };
			if (opcoesFormatadas[idx]) opcoesFormatadas[idx].rows.push(row);
			else opcoesFormatadas.push({ title: navigation, rows: [row] });
		};

		if (itensFormatados[page + 1]) addNav('Ver mais opções');
		if (page !== 0) addNav('Voltar');

		return opcoesFormatadas;		
	} catch (err) {
		throw err;
	}
}

