function run(items) {
	try {
		items = JSON.parse(items);
		const itemsFiltered = items;

		if (itemsFiltered.length === 0) return false;

        let itemsTotal = [];
        Object.values(items).map((item) => { itemsTotal = [].concat(itemsTotal, item.rows) });

        const itemsMenu = [];
        let sections = [];

        itensMenuCopy = {}
		itemsFiltered.forEach((info, indexCategories, arrayCategories) => {
            let page = [];
			return {
                title: info.title,
                rows: info.rows.forEach((row, index, array) => {
                    const item = formatterTitle(row.title.toString());
                    const itemDescription = row.description ? formatterDescription(row.description.toString()) : "";
                    let somaItensPagina = 1;
                    sections.map((section) => { somaItensPagina += section.rows.length });
                    somaItensPagina += page.length;

                    page.push({ title: item, description: itemDescription })

                    if (somaItensPagina !== 0 && (somaItensPagina % 8 === 0 && itemsTotal.length > 10) || index === array.length - 1) {
                        if(sections.length === 0 || somaItensPagina <= 8) {
                            sections.push(
                                {
                                    title: info.title,
                                    rows: page,
                                }
                            );

                            if (somaItensPagina >= 8 || (indexCategories === (arrayCategories.length - 1) && index === (array.length - 1) && sections.length > 0)) {

                                itemsMenu.push(sections);
                                sections = [];
                            }
                        } else {
                            sections.push(
                                {
                                    title: info.title,
                                    rows: page,
                                }
                            )
                            itemsMenu.push(sections);

                            sections = [];
                        }
                        page = [];
                    }
                    return { title: item, description: itemDescription }
                })
            }

		})
        return itemsMenu;
	} catch (e) {
		return false;
	}
}

